Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -18,4 +18,50 @@
 <div class="bottom"><div class="toast panel" id="toast">A city this big has room for every version of you.</div><div class="controls panel"><span class="key">W A S D</span><span class="control-label">MOVE</span><span class="key">E</span><span class="control-label">INTERACT</span><span class="key">F</span><span class="control-label">FLIGHT</span><span class="key">SHIFT</span><span class="control-label">SPRINT</span></div></div>
 <div class="touch-pad" id="touchPad"><div class="stick" id="stick"></div></div><div class="touch-actions"><button class="touch-btn" id="touchInteract">E<br>ACT</button><button class="touch-btn" id="touchFlight">F<br>FLY</button></div></div>
 <div class="start-screen" id="start"><div class="intro"><div class="kicker">A LIVING CITY / YOUR RULES</div><h1>MAKE<br>YOUR <em>OWN</em><br>AFTER.</h1><p>South Coast doesn't care who you were before tonight. Find a way in, make a name, and see what the city gives back.</p><div class="intro-row"><button class="start-btn" id="begin">ENTER THE CITY &nbsp; ↗</button><div class="intro-note">WASD TO MOVE · E TO INTERACT<br>F TO TAKE FLIGHT · EXPLORE FREELY</div></div></div></div>
 <script>
+(()=>{'use strict';
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap'),mx=mini.getContext('2d');
+const W=2400,H=1600,ROAD=108,STEP=400,TAU=Math.PI*2;
+const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
+let cw=innerWidth,ch=innerHeight,dpr=1,last=0,now=0,active=false,vehicle=false,flying=false,job=false,wanted=0,cash=8450,rep=12,done=0,missionIndex=0,toastTimer,clock=0;
+let keys=Object.create(null),rain=[],buildings=[],cars=[],sparks=[];
+const player={x:400,y:400,vx:0,vy:0,walk:0,angle:0};
+const districts=['Glassline','Old Marina','Market Row','The Solace','South Point'];
+const missions=[
+ ['A Favor After Dark','The Blue Hour needs a discreet delivery across the canal. No questions, good tip.','+$ 1,200 · +8 REP', {x:2000,y:400}],
+ ['Last Call','A regular at the Solace left a package at the wrong end of town. Get it there before dawn.','+$ 1,650 · +10 REP',{x:1200,y:1200}],
+ ['A Quiet Introduction','A gallery owner on Market Row is looking for someone with a little nerve.','+$ 1,400 · +9 REP',{x:400,y:800}],
+ ['Harbor Lights','One last run to the marina. Show them the city can count on you.','+$ 2,100 · +14 REP',{x:2000,y:1200}]
+];
+function resize(){dpr=Math.min(devicePixelRatio||1,2);cw=innerWidth;ch=innerHeight;canvas.width=Math.round(cw*dpr);canvas.height=Math.round(ch*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);seedCity()}
+function seedCity(){buildings=[];cars=[];let seed=173;const r=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
+ for(let gy=0;gy<4;gy++)for(let gx=0;gx<6;gx++){let bx=gx*STEP+ROAD/2+17,by=gy*STEP+ROAD/2+18,bw=STEP-ROAD-34,bh=STEP-ROAD-36;
+  if((gx+gy)%7===2){buildings.push({x:bx+18,y:by+18,w:bw-36,h:bh-36,hue:155+r()*25,park:true});continue}
+  let n=2+Math.floor(r()*3);for(let i=0;i<n;i++){let col=i%2,row=Math.floor(i/2),x=bx+col*bw*.5+12+r()*12,y=by+row*bh*.5+10+r()*12,w=bw*.5-29-r()*12,h=bh*.5-27-r()*13;
+    if(gx===0&&gy===0&&x<410&&y<430)continue;
+    buildings.push({x,y,w,h,hue:145+r()*50,shade:r(),label:r()>.72?'✦':''});}}
+ }
+ for(let i=0;i<18;i++)cars.push({x:ROAD/2+(i%6)*STEP+(i%2?34:-34),y:ROAD/2+Math.floor(i/6)*STEP+((i%3)-1)*30,angle:i%2?Math.PI/2:0,color:['#d9dfc9','#839c93','#b2a673','#a1b0a5','#d8ff64'][i%5]});
+ rain=Array.from({length:Math.min(170,Math.round(cw*ch/6800))},()=>({x:rand(0,cw),y:rand(0,ch),l:rand(5,16),s:rand(180,420)}));}
+function screenPoint(x,y,cam){return{x:x-cam.x+cw/2,y:y-cam.y+ch/2}}
+function camera(){return{x:clamp(player.x, cw*.5,W-cw*.5),y:clamp(player.y,ch*.5,H-ch*.5)}}
+function roundRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}
+function drawWorld(){const cam=camera();ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#13201c';ctx.fillRect(0,0,cw,ch);ctx.save();ctx.translate(cw/2-cam.x,ch/2-cam.y);
+ // blocks and the city grid
+ ctx.fillStyle='#1b2b25';ctx.fillRect(0,0,W,H);
+ for(let x=0;x<W;x+=STEP){ctx.fillStyle='#26312d';ctx.fillRect(x-ROAD/2,0,ROAD,H);ctx.fillStyle='#34413b';ctx.fillRect(x-ROAD/2,0,5,H);ctx.fillRect(x+ROAD/2-5,0,5,H);ctx.fillStyle='#d5d4b333';for(let y=22;y<H;y+=48)ctx.fillRect(x-2,y,4,22);}
+ for(let y=0;y<H;y+=STEP){ctx.fillStyle='#26312d';ctx.fillRect(0,y-ROAD/2,W,ROAD);ctx.fillStyle='#34413b';ctx.fillRect(0,y-ROAD/2,W,5);ctx.fillRect(0,y+ROAD/2-5,W,5);ctx.fillStyle='#d5d4b333';for(let x=18;x<W;x+=48)ctx.fillRect(x,y-2,22,4);}
+ // crosswalk bars
+ for(let gx=0;gx<6;gx++)for(let gy=0;gy<4;gy++){let x=gx*STEP,y=gy*STEP;ctx.fillStyle='#d9dfd522';for(let k=-3;k<=3;k++){ctx.fillRect(x+k*10,y-ROAD/2+8,5,21);ctx.fillRect(x+k*10,y+ROAD/2-29,5,21);ctx.fillRect(x-ROAD/2+8,y+k*10,21,5);ctx.fillRect(x+ROAD/2-29,y+k*10,21,5);}}
+ for(const b of buildings){if(b.park){ctx.fillStyle='#243a2d';roundRect(ctx,b.x,b.y,b.w,b.h,16);ctx.fill();ctx.strokeStyle='#63835555';ctx.lineWidth=2;ctx.stroke();for(let i=0;i<10;i++){let tx=b.x+20+(i*83%(b.w-40)),ty=b.y+20+(i*53%(b.h-40));ctx.fillStyle=i%2?'#78935b':'#426746';ctx.beginPath();ctx.arc(tx,ty,8+(i%3)*3,0,TAU);ctx.fill();ctx.fillStyle='#b8aa7755';ctx.fillRect(tx-2,ty,4,12);}continue;}
+  ctx.fillStyle='#080e0c88';roundRect(ctx,b.x+5,b.y+8,b.w,b.h,9);ctx.fill();ctx.fillStyle=`hsl(${b.hue} 12% ${14+b.shade*8}%)`;roundRect(ctx,b.x,b.y,b.w,b.h,8);ctx.fill();ctx.strokeStyle='#d4e4d514';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#ffffff0a';ctx.fillRect(b.x+9,b.y+8,b.w-18,3);
+  // roof details and warm lit windows
+  ctx.fillStyle='#26332e';ctx.fillRect(b.x+b.w*.18,b.y+b.h*.18,b.w*.64,b.h*.64);ctx.fillStyle='#d8ff6433';ctx.fillRect(b.x+b.w*.2,b.y+b.h*.19,Math.max(14,b.w*.24),3);ctx.fillStyle='#ebc77a88';for(let wx=b.x+13;wx<b.x+b.w-8;wx+=18){if((Math.floor(wx+b.y)%4)!==0)ctx.fillRect(wx,b.y+5,4,2);if((Math.floor(wx+b.h)%3)!==0)ctx.fillRect(wx,b.y+b.h-7,4,2);}if(b.label){ctx.fillStyle='#d8ff6488';ctx.font='10px monospace';ctx.fillText(b.label,b.x+b.w*.5,b.y+b.h*.52);}}
+ // street lamps
+ for(let x=ROAD/2;x<W;x+=STEP)for(let y=ROAD/2;y<H;y+=STEP){let glow=ctx.createRadialGradient(x,y,3,x,y,70);glow.addColorStop(0,'#e6d79d21');glow.addColorStop(1,'#e6d79d00');ctx.fillStyle=glow;ctx.fillRect(x-70,y-70,140,140);ctx.fillStyle='#b9aa7d';ctx.beginPath();ctx.arc(x+48,y+47,2,0,TAU);ctx.fill();}
+ // parked cars
+ for(const c of cars){ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.angle);ctx.fillStyle='#060b0a99';roundRect(ctx,-19,-10,42,23,6);ctx.fill();ctx.fillStyle=c.color;roundRect(ctx,-20,-12,40,20,6);ctx.fill();ctx.fillStyle='#253832';roundRect(ctx,-10,-9,20,14,4);ctx.fill();ctx.fillStyle='#e7d79a';ctx.fillRect(16,-8,3,4);ctx.fillRect(16,3,3,4);ctx.restore();}
+ drawMission(cam);drawPlayer();ctx.restore();drawRain();drawMini();
+}
+function drawMission(cam){let target=job?missions[missionIndex].at:null;if(!target)return;let pulse=.5+.5*Math.sin(now*4);ctx.save();ctx.translate(target.x,target.y);ctx.strokeStyle=`rgba(216,255,100,${.35+pulse*.45})`;ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,19+pulse*8,0,TAU);ctx.stroke();ctx.fillStyle='#d8ff64';ctx.beginPath();ctx.arc(0,0,5,0,TAU);ctx.fill();ctx.fillStyle='#d8ff64';ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillText('DROP',0,-31);ctx.restore();}
+function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.angle);if(vehicle){ctx.fillStyle='#05080799';roundRect(ctx,-17,-10,38,23,7);ctx.fill();ctx.fillStyle='#d8ff64';roundRect(ctx,-18,-12,36,21,7);ctx.fill();ctx.fillStyle='#23352d';roundRect(ctx,-9,-9,18,14,4);ctx.fill();ctx.fillStyle='#fff0a0';ctx.fillRect(14,-7,3,4);ctx.fillRect(14,3,3,4);}else{ctx.fillStyle='#0009';ctx.beginPath();ctx.ellipse(2,7,9,6,0,0,TAU);ctx.fill();ctx.fillStyle=flying?'#d8ff64':'#d2c8a9';ctx.beginPath();ctx.arc(0,0,flying?8:6.5,0,TAU);ctx.fill();ctx.fillStyle='#d8ff64';ctx.beginPath();ctx.moveTo(0,-11);ctx.lineTo(-4,-3);ctx.lineTo(4,-3);ctx.closePath();ctx.fill();}ctx.restore();}

input.newString:
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.angle);if(vehicle){ctx.fillStyle='#05080799';roundRect(ctx,-17,-10,38,23,7);ctx.fill();ctx.fillStyle='#d8ff64';roundRect(ctx,-18,-12,36,21,7);ctx.fill();ctx.fillStyle='#23352d';roundRect(ctx,-9,-9,18,14,4);ctx.fill();ctx.fillStyle='#fff0a0';ctx.fillRect(14,-7,3,4);ctx.fillRect(14,3,3,4);}else{ctx.fillStyle='#0009';ctx.beginPath();ctx.ellipse(2,7,9,6,0,0,TAU);ctx.fill();ctx.fillStyle=flying?'#d8ff64':'#d2c8a9';ctx.beginPath();ctx.arc(0,0,flying?8:6.5,0,TAU);ctx.fill();ctx.fillStyle='#d8ff64';ctx.beginPath();ctx.moveTo(0,-11);ctx.lineTo(-4,-3);ctx.lineTo(4,-3);ctx.closePath();ctx.fill();}ctx.restore();}
function drawRain(){ctx.save();ctx.strokeStyle='#b9d6c42a';ctx.lineWidth=1;for(const drop of rain){drop.y+=drop.s*.012;drop.x+=drop.s*.004;if(drop.y>ch){drop.y=-15;drop.x=rand(0,cw);}ctx.beginPath();ctx.moveTo(drop.x,drop.y);ctx.lineTo(drop.x-4,drop.y+drop.l);ctx.stroke();}ctx.restore();}
function drawMini(){const w=mini.width,h=mini.height;mx.clearRect(0,0,w,h);mx.fillStyle='#172822';mx.fillRect(0,0,w,h);mx.fillStyle='#39443e';for(let x=0;x<W;x+=STEP)mx.fillRect((x-ROAD/2)/W*w,0,ROAD/W*w,h);for(let y=0;y<H;y+=STEP)mx.fillRect(0,(y-ROAD/2)/H*h,w,ROAD/H*h);for(const b of buildings){if(!b.park){mx.fillStyle='#53615a';mx.fillRect(b.x/W*w,b.y/H*h,b.w/W*w,b.h/H*h);}else{mx.fillStyle='#638355';mx.fillRect(b.x/W*w,b.y/H*h,b.w/W*w,b.h/H*h);}}if(job){const t=missions[missionIndex].at;mx.fillStyle='#d8ff64';mx.beginPath();mx.arc(t.x/W*w,t.y/H*h,5,0,TAU);mx.fill();}mx.fillStyle='#eef4eb';mx.beginPath();mx.arc(player.x/W*w,player.y/H*h,5,0,TAU);mx.fill();mx.strokeStyle='#d8ff64';mx.lineWidth=1.5;mx.stroke();}
function collides(x,y){const r=vehicle?11:7;for(const b of buildings){if(b.park)continue;if(x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)return true;}return false;}
function setCash(){document.getElementById('cash').textContent='$ '+cash.toLocaleString();document.getElementById('rep').innerHTML=rep+' <small>REP</small>';}
function say(text){const el=document.getElementById('toast');el.textContent=text;el.style.opacity='1';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.opacity='',3900);}
function feed(text){const el=document.createElement('div');el.className='feed-item';el.innerHTML=text;document.getElementById('feed').prepend(el);setTimeout(()=>el.remove(),5100);}
function changeWanted(n){wanted=clamp(wanted+n,0,5);document.querySelectorAll('#heat i').forEach((e,i)=>e.classList.toggle('on',i<wanted));}
function updateDistrict(){const gx=Math.floor(player.x/STEP),gy=Math.floor(player.y/STEP);const name=gy===0?(gx<2?'Glassline':'The Solace'):gy===1?(gx<3?'Market Row':'Glassline'):gy===2?(gx<3?'Old Marina':'South Point'):'Old Marina';document.getElementById('district').textContent=name;const minute=Math.floor(now*2),m=(42+minute)%60,hour=1+Math.floor((42+minute)/60);document.getElementById('clock').textContent=String(hour%12||12).padStart(2,'0')+':'+String(m).padStart(2,'0');}
function update(dt){let up=keys.w||keys.arrowup,down=keys.s||keys.arrowdown,left=keys.a||keys.arrowleft,right=keys.d||keys.arrowright;let ix=Number(right)-Number(left),iy=Number(down)-Number(up),len=Math.hypot(ix,iy);if(len){ix/=len;iy/=len;}const speed=vehicle?310:flying?290:keys.shift?205:140;const accel=vehicle?8:12;player.vx+=(ix*speed-player.vx)*Math.min(1,accel*dt);player.vy+=(iy*speed-player.vy)*Math.min(1,accel*dt);if(!len){player.vx*=Math.pow(.025,dt);player.vy*=Math.pow(.025,dt);}const nx=clamp(player.x+player.vx*dt,12,W-12),ny=clamp(player.y+player.vy*dt,12,H-12);if(flying||!collides(nx,player.y))player.x=nx;else player.vx=0;if(flying||!collides(player.x,ny))player.y=ny;else player.vy=0;if(Math.hypot(player.vx,player.vy)>8){player.angle=Math.atan2(player.vy,player.vx);player.walk+=dt*10;}if(vehicle&&Math.hypot(player.vx,player.vy)>125&&Math.random()<dt*.025){changeWanted(1);say('A patrol clocked your speed. Ease off and keep moving.');}if(wanted&&now-lastCrime>22){changeWanted(-1);lastCrime=now;}}
let lastCrime=0;
function frame(ts){const dt=Math.min(.04,(ts-last)/1000||0);last=ts;now=ts/1000;update(dt);drawWorld();updateDistrict();if(job){const t=missions[missionIndex].at,d=Math.round(dist(player,t));document.getElementById('objective').innerHTML='ACTIVE LEAD &nbsp; <b>'+d+' M</b>';if(d<55){document.getElementById('objective').innerHTML='DELIVERY POINT &nbsp; <b>PRESS E</b>';}}else document.getElementById('objective').innerHTML=done>=4?'NIGHT COMPLETE &nbsp; <b>CITY LEGEND</b>':'CITY STATUS &nbsp; <b>FREE ROAM</b>';requestAnimationFrame(frame);}
function start(){if(active)return;active=true;document.getElementById('start').classList.add('hidden');document.getElementById('mode').classList.add('show');say('Welcome to South Coast. The night is yours.');feed('<b>01:42</b> &nbsp; You stepped into Glassline.');}
function toggleFlight(){if(!active)start();flying=!flying;if(flying)vehicle=false;document.getElementById('mode').textContent=flying?'FLIGHT MODE · FREE ROAM':vehicle?'IN A CAR · FREE ROAM':'ON FOOT · FREE ROAM';say(flying?'You lift above the boulevard. Take in the whole city.':'Back on the street.');}
function interact(){if(!active){start();return;}if(job&&dist(player,missions[missionIndex].at)<58){completeJob();return;}if(vehicle){vehicle=false;document.getElementById('mode').textContent='ON FOOT · FREE ROAM';say('You step out onto the street.');return;}let nearest=null,nd=62;for(const car of cars){const d=dist(player,car);if(d<nd){nearest=car;nd=d;}}if(nearest){player.x=nearest.x;player.y=nearest.y;vehicle=true;flying=false;player.vx=player.vy=0;document.getElementById('mode').textContent='IN A CAR · FREE ROAM';say('You slide into a parked coupe. Take the scenic route.');feed('<b>VEHICLE</b> &nbsp; Keys in the ignition.');return;}if(job){say('Follow the lime marker on your field map to the drop point.');return;}say('Walk up to a parked car and press E to take the wheel.');}
function takeJob(){if(!active)start();if(done>=4){say('You have done all four runs. The whole coast knows your name.');return;}if(job){say('You already have an active lead. Follow the marker on your map.');return;}job=true;const m=missions[missionIndex];document.getElementById('accept').textContent='TRACKING ✓';document.getElementById('jobcount').textContent=String(done+1).padStart(2,'0')+' / 04';say('Lead accepted. The lime marker is live on your field map.');feed('<b>NEW LEAD</b> &nbsp; '+m[0]);}
function completeJob(){const m=missions[missionIndex],rew=[1200,1650,1400,2100][missionIndex],repGain=[8,10,9,14][missionIndex];job=false;cash+=rew;rep+=repGain;done++;missionIndex=(missionIndex+1)%missions.length;setCash();document.getElementById('accept').textContent=done>=4?'NIGHT COMPLETE':'TAKE JOB ↗';document.getElementById('jobcount').textContent=done>=4?'04 / 04':String(done+1).padStart(2,'0')+' / 04';say(done>=4?'Four runs, four wins. South Coast is yours tonight.':'Delivery complete. +$'+rew.toLocaleString()+' and the right people know your name.');feed('<b>JOB COMPLETE</b> &nbsp; +$'+rew.toLocaleString()+' · +'+repGain+' REP');if(done>=4)feed('<b>CITY LEGEND</b> &nbsp; Every lead delivered.');}
function action(kind){if(!active)start();if(kind==='business'){if(ownsBusiness){say('Glasshouse Coffee is open. Your first venture is already paying off.');return;}if(cash<3000){say('You need $3,000 for a storefront deposit. Take a job first.');return;}cash-=3000;rep+=4;ownsBusiness=true;setCash();say('A tiny storefront on Market Row is yours. First chapter of something bigger.');feed('<b>NEW VENTURE</b> &nbsp; Glasshouse Coffee');}
 if(kind==='property'){if(ownsHome){say('Your loft above the Old Marina is already yours.');return;}if(cash<1800){say('The landlord wants $1,800 up front.');return;}cash-=1800;ownsHome=true;setCash();say('Keys to a compact loft above the old marina. Make it home.');feed('<b>PROPERTY</b> &nbsp; Old Marina · Loft 4B');}
 if(kind==='social'){if(now<socialReady){say('Let the conversation breathe. Circle back in a little while.');return;}rep+=2;socialReady=now+15;setCash();say('You made a good impression at the Solace. New numbers in your phone.');feed('<b>CONNECTION</b> &nbsp; The city remembers a face.');}
 if(kind==='mayhem'){changeWanted(1);lastCrime=now;say('A siren sounds somewhere behind you. The night just got complicated.');feed('<b>DISRUPTION</b> &nbsp; Heat is rising. Lay low.');}}
let ownsBusiness=false,ownsHome=false,socialReady=0;
document.getElementById('begin').onclick=start;document.getElementById('accept').onclick=takeJob;document.querySelectorAll('.action').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='enter'&&!e.repeat){if(job&&active)interact();else takeJob();}if(k==='e'&&!e.repeat)interact();if(k==='f'&&!e.repeat)toggleFlight();});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});window.addEventListener('blur',()=>{keys=Object.create(null);});window.addEventListener('resize',resize);
const pad=document.getElementById('touchPad'),stick=document.getElementById('stick');let padPointer=null;
pad.addEventListener('pointerdown',e=>{e.preventDefault();padPointer=e.pointerId;pad.setPointerCapture(e.pointerId);moveStick(e);if(!active)start();});pad.addEventListener('pointermove',e=>{if(e.pointerId===padPointer)moveStick(e);});function moveStick(e){const r=pad.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=39,d=Math.hypot(dx,dy),scale=d>max?max/d:1;stick.style.transform='translate('+dx*scale+'px,'+dy*scale+'px)';keys.a=dx< -12;keys.d=dx>12;keys.w=dy< -12;keys.s=dy>12;}
function releasePad(){padPointer=null;stick.style.transform='';keys.a=keys.d=keys.w=keys.s=false;}pad.addEventListener('pointerup',releasePad);pad.addEventListener('pointercancel',releasePad);document.getElementById('touchInteract').addEventListener('pointerdown',e=>{e.preventDefault();interact();});document.getElementById('touchFlight').addEventListener('pointerdown',e=>{e.preventDefault();toggleFlight();});
resize();requestAnimationFrame(frame);
})();
</script></body></html>

